42	
43	std::unique_ptr<Dict> parse(const std::string& magnet)
44	{
45	  if (!util::startsWith(magnet, "magnet:?")) {
46	    return nullptr;
47	  }
48	  auto dict = Dict::g();
49	  std::vector<Scip> queries;
50	  util::splitIter(magnet.begin() + 8, magnet.end(), std::back_inserter(queries),
51	                  '&');
52	  for (std::vector<Scip>::const_iterator i = queries.begin(),
53	                                         eoi = queries.end();
54	       i != eoi; ++i) {
55	    auto p = util::divide((*i).first, (*i).second, '=');
56	    std::string name(p.first.first, p.first.second);
57	    std::string value(util::percentDecode(p.second.first, p.second.second));
58	    List* l = downcast<List>(dict->get(name));
59	    if (l) {
60	      l->append(String::g(value));
61	    }
62	    else {
63	      auto l = List::g();
64	      l->append(String::g(value));
65	      dict->put(name, std::move(l));
66	    }
67	  }
68	  return dict;
69	}
