78	void UTMetadataPostDownloadHandler::getNextRequestGroups(
79	    std::vector<std::shared_ptr<RequestGroup>>& groups,
80	    RequestGroup* requestGroup) const
81	{
82	  auto& dctx = requestGroup->getDownloadContext();
83	  auto attrs = bittorrent::getTorrentAttrs(dctx);
84	  std::string metadata =
85	      util::toString(requestGroup->getPieceStorage()->getDiskAdaptor());
86	  std::string torrent = bittorrent::metadata2Torrent(metadata, attrs);
87	
88	  if (requestGroup->getOption()->getAsBool(PREF_BT_SAVE_METADATA)) {
89	    std::string filename =
90	        util::applyDir(requestGroup->getOption()->get(PREF_DIR),
91	                       util::toHex(attrs->infoHash) + ".torrent");
92	    if (util::saveAs(filename, torrent)) {
93	      A2_LOG_NOTICE(fmt(MSG_METADATA_SAVED, filename.c_str()));
94	    }
95	    else {
96	      A2_LOG_NOTICE(fmt(MSG_METADATA_NOT_SAVED, filename.c_str()));
97	    }
98	  }
99	  if (!requestGroup->getOption()->getAsBool(PREF_BT_METADATA_ONLY)) {
100	    std::vector<std::shared_ptr<RequestGroup>> newRgs;
101	    // Don't adjust announce URI because it has been done when
102	    // RequestGroup is created with magnet URI.
103	    createRequestGroupForBitTorrent(newRgs, requestGroup->getOption(),
104	                                    std::vector<std::string>(), A2STR::NIL,
105	                                    torrent, false);
106	    requestGroup->followedBy(newRgs.begin(), newRgs.end());
107	    for (auto& rg : newRgs) {
108	      rg->following(requestGroup->getGID());
109	    }
110	    if (requestGroup->getMetadataInfo()) {
111	      setMetadataInfo(newRgs.begin(), newRgs.end(),
112	                      requestGroup->getMetadataInfo());
113	    }
114	    auto rgman = requestGroup->getRequestGroupMan();
115	
116	    if (rgman && rgman->getKeepRunning() &&
117	        requestGroup->getOption()->getAsBool(PREF_PAUSE_METADATA)) {
118	      for (auto& rg : newRgs) {
119	        rg->setPauseRequested(true);
120	      }
121	    }
122	
123	    groups.insert(groups.end(), newRgs.begin(), newRgs.end());
124	  }
125	}
