64	namespace {
65	void copyValues(const std::shared_ptr<FileEntry>& d,
66	                const std::shared_ptr<FileEntry>& s)
67	{
68	  d->setRequested(true);
69	  d->setPath(s->getPath());
70	  d->addUris(std::begin(s->getRemainingUris()),
71	             std::end(s->getRemainingUris()));
72	  d->setMaxConnectionPerServer(s->getMaxConnectionPerServer());
73	  d->setUniqueProtocol(s->isUniqueProtocol());
74	}
