79	  bool operator()(const std::shared_ptr<FileEntry>& lhs,
80	                  const std::shared_ptr<FileEntry>& rhs) const
81	  {
82	    return lhs->getOriginalName() < rhs->getOriginalName();
83	  }
84	};
