86	
87	bool BtDependency::resolve()
88	{
89	  if (!dependee_) {
90	    return true;
91	  }
92	  if (dependee_->getNumCommand() == 0 && dependee_->downloadFinished()) {
93	    std::shared_ptr<RequestGroup> dependee = dependee_;
94	    // cut reference here
95	    dependee_.reset();
96	    auto context = std::make_shared<DownloadContext>();
97	    try {
98	      std::shared_ptr<DiskAdaptor> diskAdaptor =
99	          dependee->getPieceStorage()->getDiskAdaptor();
100	      diskAdaptor->openExistingFile();
101	      std::string content = util::toString(diskAdaptor);
102	      if (dependee->getDownloadContext()->hasAttribute(CTX_ATTR_BT)) {
103	        auto attrs =
104	            bittorrent::getTorrentAttrs(dependee->getDownloadContext());
105	        bittorrent::loadFromMemory(bittorrent::metadata2Torrent(content, attrs),
106	                                   context, dependant_->getOption(), "default");
107	        // We don't call bittorrent::adjustAnnounceUri() because it
108	        // has already been called with attrs.
109	      }
110	      else {
111	        bittorrent::loadFromMemory(
112	            content, context, dependant_->getOption(),
113	            File(dependee->getFirstFilePath()).getBasename());
114	        bittorrent::adjustAnnounceUri(bittorrent::getTorrentAttrs(context),
115	                                      dependant_->getOption());
116	      }
117	      const std::vector<std::shared_ptr<FileEntry>>& fileEntries =
118	          context->getFileEntries();
119	      for (auto& fe : fileEntries) {
120	        auto& uri = fe->getRemainingUris();
121	        std::shuffle(std::begin(uri), std::end(uri),
122	                     *SimpleRandomizer::getInstance());
123	      }
124	      const std::vector<std::shared_ptr<FileEntry>>& dependantFileEntries =
125	          dependant_->getDownloadContext()->getFileEntries();
126	      // If dependant's FileEntry::getOriginalName() is empty, we
127	      // assume that torrent is single file. In Metalink3, this is
128	      // always assumed.
129	      if (fileEntries.size() == 1 && dependantFileEntries.size() == 1 &&
130	          dependantFileEntries[0]->getOriginalName().empty()) {
131	        // TODO this may be dead code
132	        copyValues(fileEntries[0], dependantFileEntries[0]);
133	      }
134	      else {
135	        std::vector<std::shared_ptr<FileEntry>> destFiles;
136	        destFiles.reserve(fileEntries.size());
137	        for (auto& e : fileEntries) {
138	          e->setRequested(false);
139	          destFiles.push_back(e);
140	        }
141	        std::sort(std::begin(destFiles), std::end(destFiles), EntryCmp());
142	        // Copy file path in dependant_'s FileEntries to newly created
143	        // context's FileEntries to endorse the path structure of
144	        // dependant_.  URIs and singleHostMultiConnection are also copied.
145	        for (const auto& e : dependantFileEntries) {
146	          const auto d = std::lower_bound(std::begin(destFiles),
147	                                          std::end(destFiles), e, EntryCmp());
148	          if (d == std::end(destFiles) ||
149	              (*d)->getOriginalName() != e->getOriginalName()) {
150	            throw DL_ABORT_EX(fmt("No entry %s in torrent file",
151	                                  e->getOriginalName().c_str()));
152	          }
153	          else {
154	            copyValues(*d, e);
155	          }
156	        }
157	      }
158	    }
159	    catch (RecoverableException& e) {
160	      A2_LOG_ERROR_EX(EX_EXCEPTION_CAUGHT, e);
161	      A2_LOG_INFO(fmt("BtDependency for GID#%s failed. Go without Bt.",
162	                      GroupId::toHex(dependant_->getGID()).c_str()));
163	      return true;
164	    }
165	    A2_LOG_INFO(fmt("Dependency resolved for GID#%s",
166	                    GroupId::toHex(dependant_->getGID()).c_str()));
167	    dependant_->setDownloadContext(context);
168	    return true;
169	  }
170	  else if (dependee_->getNumCommand() == 0) {
171	    // dependee_'s download failed.
172	    // cut reference here
173	    dependee_.reset();
174	    A2_LOG_INFO(fmt("BtDependency for GID#%s failed. Go without Bt.",
175	                    GroupId::toHex(dependant_->getGID()).c_str()));
176	    return true;
177	  }
178	  else {
179	    return false;
180	  }
