    if (torrent) {
      auto rg = createBtRequestGroup(torrentFilename, optionTemplate, {},
                                     torrent.get());
      const auto& actualInfoHash =
          bittorrent::getTorrentAttrs(rg->getDownloadContext())->infoHash;

      if (torrentAttrs->infoHash == actualInfoHash) {
