{
  UTMetadataPostDownloadHandler handler;

  CPPUNIT_ASSERT(!handler.canHandle(requestGroup_.get()));

  dctx_->setAttribute(CTX_ATTR_BT, make_unique<TorrentAttribute>());

  CPPUNIT_ASSERT(handler.canHandle(requestGroup_.get()));

